{
  "implementation": "def solve(case):
    try:
        initial = case['initial_state']
        max_steps = case['max_steps']
        tool_obs = case['tool_observations']
        trans = case['transitions']
    except KeyError as e:
        raise ValueError(f"Missing key: {e}")

    if initial not in trans:
        raise ValueError(f"Initial state {initial!r} not in transitions")

    # Handle immediate final initial state
    if trans[initial]['kind'] == 'final':
        return {
            "final": trans[initial]['value'],
            "status": "completed",
            "trace": []
        }

    current = initial
    trace = []
    steps = 0
    final_val = None
    status = "max_steps_reached"

    while steps < max_steps:
        t = trans[current]
        if t['kind'] != 'action':
            raise ValueError(f"State {current!r} has kind {t['kind']!r}, expected 'action'")
        action = t['action']
        if action not in tool_obs:
            raise ValueError(f"Tool {action!r} not in tool_observations")
        obs = tool_obs[action]
        next_state = t['next_by_observation'].get(obs, t.get('default_next'))
        if next_state is None:
            raise ValueError(
                f"No next state for state {current!r}, action {action!r}, observation {obs!r}"
            )
        if next_state not in trans:
            raise ValueError(f"Next state {next_state!r} not defined in transitions")
        trace.append({
            "step": steps,
            "action": action,
            "observation": obs,
            "state": current
        })
        current = next_state
        steps += 1
        if trans[current]['kind'] == 'final':
            final_val = trans[current]['value']
            status = "completed"
            break

    return {
        "final": final_val,
        "status": status,
        "trace": trace
    }
